import{_ as e,o,c as a,a2 as l}from"./chunks/framework.Crpw6aS5.js";const h=JSON.parse('{"title":"2018年 · 放弃账面价值","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/2018年.md","filePath":"05_quotes/by-year/2018年.md"}'),r={name:"05_quotes/by-year/2018年.md"};function u(q,t,c,p,s,_){return o(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="_2018年-·-放弃账面价值" tabindex="-1">2018年 · 放弃账面价值 <a class="header-anchor" href="#_2018年-·-放弃账面价值" aria-label="Permalink to &quot;2018年 · 放弃账面价值&quot;">​</a></h1><blockquote><p>现在是放弃这种做法的时候了。事实是，伯克希尔账面价值的年度变化——它在第2页最后一次亮相——这一指标已经失去了它曾经具有的相关性。——巴菲特（88岁）</p></blockquote><p>本页收录2018年致股东信中的经典语录。本年巴菲特正式告别账面价值指标，首次提出&quot;五大树林&quot;战略框架，并以&quot;美国顺风&quot;论述回应了对美国经济的长期乐观主义。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>在伯克希尔，整体远大于部分之和。</p></blockquote><blockquote><p>查理和我不会将这1728亿美元视为一堆股票代码的集合——相反，我们在持仓中看到的是一个我们部分拥有的公司组合，按加权计算，这些公司在运营业务所需的净有形权益资本上赚取约20%的收益。</p></blockquote><blockquote><p>理性的人不会冒险失去他们拥有和需要的东西，去换取他们没有和不需要的东西。</p></blockquote><blockquote><p>伯克希尔将永远是一座金融堡垒。在管理中，我会犯下昂贵的错误，也会错失许多机会，其中一些本应对我来说是显而易见的。但我永远不会冒险出现现金短缺。</p></blockquote><blockquote><p>查理和我欣然承认，伯克希尔的大部分成功仅仅是我想应该称之为&quot;美国顺风&quot;的产物。美国企业或个人吹嘘他们&quot;独自完成&quot;是傲慢至极的。</p></blockquote><blockquote><p>我们的国家几乎令人难以置信的繁荣是以两党合作的方式获得的。所有这些都引发了可怕的头条新闻；现在都已成为历史。</p></blockquote><blockquote><p>如果你想寻找我的纪念碑，请环顾四周。</p></blockquote><blockquote><p>你可能会问，如果我们出售某些全资拥有的业务，伯克希尔将产生的主要税收成本是否也应该考虑进去。忘掉这个想法吧：即使不需要缴税，出售我们任何优秀的公司也是愚蠢的。真正好的企业异常难找。</p></blockquote><blockquote><p>亚伯拉罕·林肯曾提出这样一个问题：&quot;如果你把狗的尾巴叫做腿，它有几条腿？&quot;然后他自己回答：&quot;四条，因为把尾巴叫做腿并不能让它变成腿。&quot;如果林肯活在今天的华尔街，他会感到孤独。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>2018年伯克希尔每股账面价值仅增长0.4%，市场价值增长2.8%，但标普500下跌4.4%。新GAAP准则导致季度收益剧烈波动（Q1亏损11亿，Q2盈利120亿，Q3盈利185亿，Q4亏损254亿）。巴菲特宣布放弃账面价值指标，首次提出五大树林框架。全年买入430亿美元股票，仅卖出190亿美元。苹果成为最大持仓（403亿美元）。为纪念托尼·奈斯利的传奇职业生涯，本年信专门设立一个章节。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><p><a href="/01_letters/2018年/翻译.html">01_letters/2018年/翻译</a> · <a href="/01_letters/2018年/核心总结.html">01_letters/2018年/核心总结</a> · <a href="/01_letters/2018年/思维导图.html">01_letters/2018年/思维导图</a></p>',20)])])}const n=e(r,[["render",u]]);export{h as __pageData,n as default};
